MORPH_CONF_EOF
cat > $P/tsconfig.card.json <<'MORPH_TSCONF_EOF'
{
  "extends": "../../tsconfig.json",
  "include": [
    "../../src",
    "../../tests",
    "./*.probe.ts"
  ],
  "exclude": [
    "../../src/acceptance/types.ts",
    "../../src/acceptance/snapshot.ts"
  ]
